import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
async function scenario(fn) {
  const server=await testServer();
  try {
    const owner=server.agent();
    await owner('POST','/auth/signup',{name:'Audit owner',email:'audit-owner@example.test',password:'permission audit password'});
    const org=(await owner('POST','/orgs',{name:'Audit organization'})).data.organization;
    const project=(await owner('POST','/orgs/'+org.id+'/projects',{key:'AUD',name:'Audit project'})).data.project;
    const issue=(await owner('POST','/projects/'+project.id+'/issues',{title:'Audit issue'})).data.issue;
    const target=(await owner('POST','/projects/'+project.id+'/issues',{title:'Audit target'})).data.issue;
    const label=(await owner('POST','/projects/'+project.id+'/labels',{name:'Audit label'})).data.label;
    const comment=(await owner('POST','/issues/'+issue.id+'/comments',{body:'Audit comment'})).data.comment;
    const relation=(await owner('POST','/issues/'+issue.id+'/relations',{kind:'blocks',targetIssueId:target.id})).data.relation;
    const routes=[
      ['GET','/projects/'+project.id+'/assignees'],
      ['GET','/projects/'+project.id+'/issue-options?type=users'],
      ['GET','/labels/'+label.id],
      ['GET','/comments/'+comment.id],
      ['GET','/projects/'+project.id+'/issues'],
      ['GET','/orgs/'+org.id+'/issues'],
      ['POST','/projects/'+project.id+'/issues',{title:'Denied'}],
      ['GET','/issues/'+issue.id],
      ['PATCH','/issues/'+issue.id,{title:'Denied'}],
      ['DELETE','/issues/'+issue.id],
      ['GET','/projects/'+project.id+'/labels'],
      ['POST','/projects/'+project.id+'/labels',{name:'Denied'}],
      ['PATCH','/labels/'+label.id,{name:'Denied'}],
      ['DELETE','/labels/'+label.id],
      ['GET','/issues/'+issue.id+'/comments'],
      ['POST','/issues/'+issue.id+'/comments',{body:'Denied'}],
      ['PATCH','/comments/'+comment.id,{body:'Denied'}],
      ['DELETE','/comments/'+comment.id],
      ['GET','/issues/'+issue.id+'/relations'],
      ['POST','/issues/'+issue.id+'/relations',{kind:'relates',targetIssueId:target.id}],
      ['DELETE','/relations/'+relation.id]
    ];
    await fn({server,owner,org,project,issue,target,label,comment,relation,routes});
  }finally{await server.close();}
}
test('all issue label comment relation and candidate routes reject anonymous and unrelated accounts',()=>scenario(async({server,owner,issue,routes})=>{
  const anonymous=server.agent(),outsider=server.agent();
  await outsider('POST','/auth/signup',{name:'Unrelated',email:'unrelated@example.test',password:'permission audit password'});
  for(const [method,path,body] of routes){
    assert.equal((await anonymous(method,path,body)).status,401,'anonymous '+method+' '+path);
    assert.equal((await outsider(method,path,body)).status,403,'outsider '+method+' '+path);
  }
  assert.equal((await owner('GET','/issues/'+issue.id)).data.issue.title,'Audit issue');
  assert.equal((await owner('GET','/issues/'+issue.id+'/comments')).data.items[0].body,'Audit comment');
}));
test('granted guest access permits reads and own comments while every issue mutation stays denied',()=>scenario(async({server,owner,org,project,issue,routes})=>{
  const guest=server.agent();const signup=await guest('POST','/auth/signup',{name:'Granted Guest',email:'granted@example.test',password:'permission audit password'});
  await owner('POST','/orgs/'+org.id+'/members',{userId:signup.data.user.id,role:'guest'});
  await owner('POST','/projects/'+project.id+'/guests',{userId:signup.data.user.id});
  for(const [method,path,body] of routes){
    if(method==='GET')assert.equal((await guest(method,path,body)).status,200,'guest read '+path);
    else if(path.endsWith('/comments')&&method==='POST')continue;
    else assert.equal((await guest(method,path,body)).status,403,'guest mutation '+method+' '+path);
  }
  const created=await guest('POST','/issues/'+issue.id+'/comments',{body:'Guest can discuss'});assert.equal(created.status,201);
  assert.equal((await guest('PATCH','/comments/'+created.data.comment.id,{body:'Guest edited'})).status,200);
  assert.equal((await guest('DELETE','/comments/'+created.data.comment.id)).status,200);
}));

import {useState,useRef} from 'preact/hooks';
import {Field,Button,Notice} from '../../components/ui.jsx';
import {PRIORITIES} from '../../../../shared/src/schemas/issue.js';
import {issueForm,issuePayload,issueErrors,changedFields,insertMention} from './issue-state.js';
import {WorkPicker,LabelSelection,RevisionDecision} from './issue-controls.jsx';
import {Markdown} from './issue-discussion.jsx';
export function IssueEditor({api,issue,project,onSave,onCancel}) {
  const [baseline,setBaseline]=useState(issue);
  const [form,setForm]=useState(()=>issueForm(issue));
  const [error,setError]=useState(null),[latest,setLatest]=useState(null);
  const [busy,setBusy]=useState(false),[preview,setPreview]=useState(false);
  const pending=useRef(false);
  const errors=issueErrors(error),accessLost=[401,403,404].includes(error?.status);
  function change(field,value){setForm(previous=>({...previous,[field]:value}));}
  function input(field){return event=>change(field,event.currentTarget.value);}
  function load(record){setBaseline(record);setForm(issueForm(record));setError(null);setLatest(null);}
  async function inspect(){try{setLatest((await api.get('/issues/'+issue.id)).issue);}catch(next){setError(next);}}
  function keep(record){
    const changes=changedFields(issuePayload(issueForm(baseline)),issuePayload(form));
    setBaseline(record);setForm(issueForm({...record,...changes,labelIds:changes.labelIds??record.labels.map(label=>label.id),labels:undefined}));setError(null);setLatest(null);
  }
  async function submit(event) {
    event.preventDefault();if(pending.current||accessLost)return;pending.current=true;setError(null);setLatest(null);setBusy(true);
    try {
      const payload=issuePayload(form);
      const body=baseline?{...changedFields(issuePayload(issueForm(baseline)),payload),expectedRevision:baseline.revision}:payload;
      if(baseline&&Object.keys(body).length===1){onCancel();return;}
      await onSave(body);
    }catch(error){setError(error);}finally{pending.current=false;setBusy(false);}
  }
  return <form className="issue-editor" onSubmit={submit}>
    <RevisionDecision error={error} latest={latest} onInspect={issue?inspect:null} onLoad={load} onKeep={keep} busy={busy}/>
    <fieldset disabled={busy}>
      <legend>{issue?'Edit issue':'New issue'}</legend>
      <Field label="Title" name="title" required maxLength={300} value={form.title} onInput={input('title')} error={errors.title}/>
      <Field label="Description (Markdown)" error={errors.description}><textarea name="description" rows="8" maxLength={100000} value={form.description} onInput={input('description')}/></Field>
      <WorkPicker api={api} project={project} type="users" permission="issue:write" label="Mention in description" value="" onChange={(id,item)=>{if(item)change('description',insertMention(form.description,{...item,userId:id}));}}/>
      <Button type="button" onClick={()=>setPreview(value=>!value)}>{preview?'Hide description preview':'Preview description'}</Button>
      {preview&&<section aria-label="Description preview"><Markdown source={form.description}/></section>}
      <p className="field-help">Raw HTML is displayed as text. Clearing an optional field removes its saved value.</p>
      <div className="form-grid">
        <Field label="Status" error={errors.statusId}><select name="statusId" value={form.statusId} onChange={input('statusId')}><option value="">First workflow status</option>{project.statuses.map(status=><option key={status.id} value={status.id}>{status.name}</option>)}</select></Field>
        <Field label="Priority" error={errors.priority}><select name="priority" value={form.priority} onChange={input('priority')}>{PRIORITIES.map(priority=><option key={priority.value} value={priority.value}>{priority.label}</option>)}</select></Field>
        <div><WorkPicker api={api} project={project} type="users" permission="issue:write" label="Assignee" value={form.assigneeId} onChange={id=>change('assigneeId',id)} placeholder="Unassigned"/><Notice error={errors.assigneeId}/></div>
        <Field label="Estimate" name="estimate" type="number" min="0" max="1000000" step="any" value={form.estimate} onInput={input('estimate')} error={errors.estimate}/>
        <Field label="Due date" name="dueDate" type="date" value={form.dueDate} onInput={input('dueDate')} error={errors.dueDate}/>
        <div><WorkPicker api={api} project={project} type="parents" issueId={issue?.id} permission="issue:write" label="Parent issue" value={form.parentId} onChange={id=>change('parentId',id)} placeholder="No parent"/><Notice error={errors.parentId}/></div>
      </div>
      <LabelSelection api={api} project={project} initial={issue?.labels} value={form.labelIds} onChange={value=>change('labelIds',value)}/><Notice error={errors.labelIds}/>
    </fieldset>
    <div className="actions"><Button busy={busy} disabled={accessLost} type="submit">{issue?'Save issue':'Create issue'}</Button><Button type="button" onClick={onCancel} disabled={busy}>Cancel</Button></div>
  </form>;
}

import {useState,useRef} from 'preact/hooks';
import {Page,Field,Button,Notice,Empty,Loading,ConfirmButton} from '../../components/ui.jsx';
import {useScopedLoad} from '../insight/scoped-load.js';
import {useIssuePages,PageMore,RevisionDecision} from './issue-controls.jsx';
export function ProjectLabels(props) {return <Labels key={props.params.projectId} {...props}/>;}
function Labels({params,api}) {
  const projectId=params.projectId;
  const result=useScopedLoad(projectId,()=>api.get('/projects/'+projectId),[projectId]);
  const [q,setQ]=useState(''),[name,setName]=useState(''),[color,setColor]=useState('#5965d8');
  const list=useIssuePages(api,'/projects/'+projectId+'/labels?q='+encodeURIComponent(q));
  const [editing,setEditing]=useState(null),[error,setError]=useState(null),[latest,setLatest]=useState(null),[busy,setBusy]=useState(false);
  const pending=useRef(false);
  const accessLost=[401,403,404].includes(error?.status);
  function cancel(){setEditing(null);setName('');setColor('#5965d8');setError(null);setLatest(null);}
  function edit(label){setEditing(label);setName(label.name);setColor(label.color);setError(null);setLatest(null);}
  async function inspect(){try{setLatest((await api.get('/labels/'+editing.id)).label);}catch(next){setError(next);}}
  async function save(event){
    event.preventDefault();if(pending.current||accessLost)return;pending.current=true;setBusy(true);setError(null);setLatest(null);
    try{
      if(editing)await api.patch('/labels/'+editing.id,{name,color,expectedRevision:editing.revision});
      else await api.post('/projects/'+projectId+'/labels',{name,color});
      cancel();list.reload();
    }catch(error){setError(error);}finally{pending.current=false;setBusy(false);}
  }
  async function remove(label){if(pending.current)return;pending.current=true;setBusy(true);try{await api.delete('/labels/'+label.id);if(editing?.id===label.id)cancel();list.reload();}catch(error){setError(error);}finally{setBusy(false);}}
  if(result.loading)return <Loading/>;
  if(result.error)return <Notice error={result.error}/>;
  const editable=!result.data.project.archived&&result.data.permissions.write;
  return <Page title={result.data.project.key+' labels'} actions={<a href={'#/projects/'+projectId+'/issues'}>Issues</a>}>
    {result.data.project.archived&&<Notice>This project is archived and read-only.</Notice>}
    <RevisionDecision error={error} latest={latest} onInspect={editing?inspect:null} onLoad={edit} busy={busy}/>
    {editable&&<form onSubmit={save}><fieldset disabled={busy}><legend>{editing?'Edit label':'New label'}</legend>
      <Field label="Label name" name="name" value={name} required maxLength={60} error={error?.details?.name} onInput={event=>setName(event.currentTarget.value)}/>
      <Field label="Color" name="color" type="color" value={color} error={error?.details?.color} onInput={event=>setColor(event.currentTarget.value)}/>
      <Button busy={busy} disabled={accessLost}>{editing?'Save label':'Create label'}</Button><Button type="button" onClick={cancel}>Cancel editing</Button>
    </fieldset></form>}
    <Field label="Search labels" name="labelSearch" type="search" value={q} onInput={event=>setQ(event.currentTarget.value)}/>
    {list.items.length?<ul>{list.items.map(label=><li key={label.id}><span className="label-chip" style={{borderColor:label.color}}>{label.name}</span>{editable&&<><Button disabled={busy} onClick={()=>{if(!editing||globalThis.confirm('Discard your current label draft?'))edit(label);}}>Edit {label.name}</Button><ConfirmButton disabled={busy} message={'Remove '+label.name+' from this project and its issues?'} onConfirm={()=>remove(label)}>Delete {label.name}</ConfirmButton></>}</li>)}</ul>:!list.loading&&!list.error&&<Empty>No labels match.</Empty>}
    <PageMore list={list} label="labels"/>
  </Page>;
}
